#Requires -Version 7.2
[CmdletBinding()]
param(
  [ValidateSet('Plan','Apply','Finalize','Verify')][string]$Action='Plan',
  [string]$RuntimeConfigPath,[string]$ExpectedRuntimeConfigSha256,[string]$MigrationPgPassFile,[string]$ExpectedMigrationPgPassSha256,[string]$FileSystemEvidencePath,[string]$ExpectedFileSystemEvidenceSha256,
  [string]$PreDatabaseBoundaryEvidencePath,[string]$ExpectedPreDatabaseBoundaryEvidenceSha256,
  [string]$PostDatabaseBoundaryEvidencePath,[string]$ExpectedPostDatabaseBoundaryEvidenceSha256,
  [string]$LatestBackupEvidencePath,[string]$ExpectedLatestBackupEvidenceSha256,[string]$BackupReceiptPublicKeyPath,[string]$ExpectedBackupReceiptPublicKeySha256,
  [ValidateSet('LOCAL_RELEASE','LEGACY_BASELINE')][string]$PreviousReleaseKind='LOCAL_RELEASE',[string]$PreviousReleaseRoot,[string]$ExpectedPreviousManifestSha256,[string]$LegacyBaselineEvidencePath,[string]$ExpectedLegacyBaselineEvidenceSha256,[string]$TargetReleaseRoot,[string]$ExpectedTargetManifestSha256,
  [string]$LegacyQuiesceEvidencePath,[string]$ExpectedLegacyQuiesceEvidenceSha256,
  [string]$CompatibilityEvidencePath,[string]$ExpectedCompatibilityEvidenceSha256,[string]$CompatibilityGeneratorPath,[string]$ExpectedCompatibilityGeneratorSha256,
  [string]$MaintenanceFlagPath,[string]$ExpectedMaintenanceFlagSha256,[string]$DrainStatePath,[string]$ExpectedDrainStateSha256,
  [string]$NodePath,[string]$ExpectedNodeSha256,[string]$AttestationVerifierPath,[string]$ExpectedAttestationVerifierSha256,
  [string]$PrismaCliPath,[string]$ExpectedPrismaCliSha256,[string]$PrismaSchemaPath,[string]$MigrationsRoot,
  [string]$PsqlPath,[string]$ExpectedPsqlSha256,
  [string]$ConfirmProjectRef,[string]$ConfirmDatabaseHost,[string]$ConfirmDatabaseName,[string]$ConfirmDatabaseSchema,
  [string]$JournalPath,[string]$ExpectedMigrationJournalSha256,[string]$EvidenceOutputPath,
  [ValidateSet(14400)][int]$MaximumMaintenanceDurationSeconds=14400,
  [ValidateRange(1,300)][int]$PgConnectTimeoutSeconds=15,
  [ValidateRange(1000,3600000)][int]$PgLockTimeoutMilliseconds=30000,
  [ValidateRange(1000,14400000)][int]$PgStatementTimeoutMilliseconds=3600000,
  [ValidateRange(1000,3600000)][int]$PgIdleTransactionTimeoutMilliseconds=60000,
  [ValidateRange(4096,8388608)][int]$MaximumChildOutputBytes=1048576,
  [ValidateSet('Apply','Finalize')][string]$PlannedAction,[string]$ApprovedPlanSha256,[switch]$Approved
)
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'approval-plan.ps1')
$script:MaintenanceStartedAt=(Get-Date).ToUniversalTime()
$script:MaintenanceDeadline=$script:MaintenanceStartedAt.AddSeconds($MaximumMaintenanceDurationSeconds)
$script:MaintenanceStopwatch=[Diagnostics.Stopwatch]::StartNew()
$script:MaintenanceMaximumMilliseconds=[long]$MaximumMaintenanceDurationSeconds*1000
function NoReparse([string]$Path){$cursor=Get-Item -LiteralPath ([IO.Path]::GetFullPath($Path)) -Force;while($cursor){if($cursor.Attributes-band[IO.FileAttributes]::ReparsePoint){throw'MIGRATION_REPARSE_REJECTED'};$cursor=$cursor.Parent}}
function File([string]$Path,[string]$Code){if(-not$Path-or-not(Test-Path -LiteralPath $Path -PathType Leaf)){throw$Code};$full=[IO.Path]::GetFullPath($Path);NoReparse $full;return $full}
function Directory([string]$Path,[string]$Code){if(-not$Path-or-not(Test-Path -LiteralPath $Path -PathType Container)){throw$Code};$full=[IO.Path]::GetFullPath($Path).TrimEnd('\');NoReparse $full;return $full}
function FileHash([string]$Path){return(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()}
function AssertHash([string]$Path,[string]$Expected,[string]$Code){if($Expected-notmatch'^[A-Fa-f0-9]{64}$'-or(FileHash $Path)-cne$Expected.ToLowerInvariant()){throw$Code}}
function Assert-MigrationExecutablePinned([string]$Path){$full=[IO.Path]::GetFullPath($Path);if($full-ieq[IO.Path]::GetFullPath($NodePath)){AssertHash (File $full 'NODE_NOT_FOUND') $ExpectedNodeSha256 'NODE_HASH_MISMATCH'}elseif($full-ieq[IO.Path]::GetFullPath($PsqlPath)){AssertHash (File $full 'PSQL_NOT_FOUND') $ExpectedPsqlSha256 'PSQL_HASH_MISMATCH'}else{throw'UNPINNED_MIGRATION_EXECUTABLE_REJECTED'}}
function Sha256Text([string]$Value){$sha=[Security.Cryptography.SHA256]::Create();try{return([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($Value))).Replace('-','').ToLowerInvariant())}finally{$sha.Dispose()}}
function Under([string]$Path,$Roots){$full=[IO.Path]::GetFullPath($Path);return @($Roots|Where-Object{$root=[IO.Path]::GetFullPath([string]$_).TrimEnd('\');$full-ieq$root-or$full.StartsWith($root+'\',[StringComparison]::OrdinalIgnoreCase)}).Count-gt0}
function OutputPath([string]$Path,[string]$Code){if(-not$Path){throw$Code};$full=[IO.Path]::GetFullPath($Path);$parent=Split-Path -Parent $full;if(-not(Test-Path -LiteralPath $parent -PathType Container)){throw$Code};NoReparse $parent;return $full}
function AtomicWrite([string]$Path,$Value){$pending="$Path.pending";if(Test-Path -LiteralPath $pending){throw'MIGRATION_PENDING_FILE_EXISTS'};try{[IO.File]::WriteAllText($pending,($Value|ConvertTo-Json -Depth 6),(New-Object Text.UTF8Encoding($false)));Move-Item -LiteralPath $pending -Destination $Path -Force}finally{Remove-Item -LiteralPath $pending -Force -ErrorAction SilentlyContinue}}
function MigrationDigest([string]$Root){$prefix=$Root.TrimEnd('\')+'\';$lines=@(Get-ChildItem -LiteralPath $Root -Filter migration.sql -File -Recurse|Sort-Object FullName|ForEach-Object{$full=[IO.Path]::GetFullPath($_.FullName);if(-not$full.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){throw'MIGRATION_PATH_ESCAPED'};$relative=$full.Substring($prefix.Length).Replace('\','/');"$relative=$((FileHash $full))"});if($lines.Count-eq0){throw'MIGRATIONS_EMPTY'};return Sha256Text ($lines-join"`n")}
function AppliedCanonical([string]$Root){return(@(Get-ChildItem -LiteralPath $Root -Filter migration.sql -File -Recurse|ForEach-Object{"$($_.Directory.Name)=$((FileHash $_.FullName))"}|Sort-Object)-join"`n")}
function PgPassword([string]$Path,[string]$Host,[string]$Database,[string]$User){$lines=@(Get-Content -LiteralPath $Path|Where-Object{$_-and-not$_.StartsWith('#')});if($lines.Count-ne1){throw'MIGRATION_PGPASS_INVALID'};$parts=[Collections.Generic.List[string]]::new();$current=New-Object Text.StringBuilder;$escaped=$false;foreach($character in $lines[0].ToCharArray()){if($escaped){$current.Append($character)|Out-Null;$escaped=$false;continue};if($character-eq'\'){$escaped=$true;continue};if($character-eq':'-and$parts.Count-lt4){$parts.Add($current.ToString());$current.Clear()|Out-Null}else{$current.Append($character)|Out-Null}};if($escaped){throw'MIGRATION_PGPASS_INVALID'};$parts.Add($current.ToString());if($parts.Count-ne5-or$parts[0]-cne$Host-or$parts[1]-ne'5432'-or$parts[2]-cne$Database-or$parts[3]-cne$User-or-not$parts[4]){throw'MIGRATION_PGPASS_INVALID'};return $parts[4]}
function ValidateBoundary([string]$Path,[string]$Expected,$Db,[datetime]$NotBefore,[string]$Code){$file=File $Path "$Code`_NOT_FOUND";AssertHash $file $Expected "$Code`_HASH_MISMATCH";$value=Get-Content -Raw -LiteralPath $file|ConvertFrom-Json;$at=[datetime]::Parse([string]$value.completedAt).ToUniversalTime();if($value.version-ne6-or$value.result-ne'PASS'-or-not$value.executorHashesVerified-or$value.psqlSha256-notmatch'^[0-9a-f]{64}$'-or-not$value.scramCredentialsVerified-or-not$value.defaultPrivilegesVerified-or-not$value.functionEscalationAbsent-or-not$value.productionRestoreRoleAccessAbsent-or-not$value.migrationRoleFullDataPrivileged-or-not$value.migrationCredentialAdminOnly-or-not$value.migrationCredentialMaintenanceOnly-or-not$value.auditAppendOnlyGuardVerified-or$value.projectRef-cne$Db.projectRef-or$value.host-cne$Db.host-or$value.databaseName-cne$Db.name-or$value.databaseSchema-cne$Db.schema-or$value.migrationRoleDigest-cne(Sha256Text ([string]$Db.migrationUser))-or($NotBefore-ne[datetime]::MinValue-and$at-lt$NotBefore)){throw$Code};return $value}
function Stop-BoundedProcessTree([Diagnostics.Process]$Process){if($null-eq$Process){return};try{if(-not$Process.HasExited){$Process.Kill($true)}}catch{try{if(-not$Process.HasExited){$Process.Kill()}}catch{}}}
function Assert-MigrationDeadline{if($script:MaintenanceStopwatch.ElapsedMilliseconds-ge$script:MaintenanceMaximumMilliseconds-or(Get-Date).ToUniversalTime()-ge$script:MaintenanceDeadline){throw'MIGRATION_MAINTENANCE_DEADLINE_EXCEEDED'}}
function Invoke-BoundedChild{
  param([string]$Executable,[string[]]$Arguments,[hashtable]$ChildEnvironment,[string]$Code)
  Assert-MigrationDeadline;Assert-MigrationExecutablePinned $Executable
  $start=[Diagnostics.ProcessStartInfo]::new();$start.FileName=$Executable;$start.UseShellExecute=$false;$start.CreateNoWindow=$true;$start.RedirectStandardOutput=$true;$start.RedirectStandardError=$true
  foreach($argument in $Arguments){[void]$start.ArgumentList.Add($argument)}
  foreach($name in @('DATABASE_URL','PGPASSWORD','PGPASSFILE','PGSSLMODE','PGSSLROOTCERT','PGOPTIONS','PGCONNECT_TIMEOUT')){[void]$start.Environment.Remove($name)}
  if($ChildEnvironment){foreach($name in $ChildEnvironment.Keys){$start.Environment[[string]$name]=[string]$ChildEnvironment[$name]}}
  $process=[Diagnostics.Process]::new();$process.StartInfo=$start;$started=$false
  $stdout=[IO.MemoryStream]::new();$stderr=[IO.MemoryStream]::new();$stdoutBuffer=New-Object byte[] 8192;$stderrBuffer=New-Object byte[] 8192
  try{
    if(-not$process.Start()){throw"$Code`_START_FAILED"};$started=$true
    $stdoutTask=$process.StandardOutput.BaseStream.ReadAsync($stdoutBuffer,0,$stdoutBuffer.Length);$stderrTask=$process.StandardError.BaseStream.ReadAsync($stderrBuffer,0,$stderrBuffer.Length);$stdoutDone=$false;$stderrDone=$false
    while(-not($process.HasExited-and$stdoutDone-and$stderrDone)){
      if($script:MaintenanceStopwatch.ElapsedMilliseconds-ge$script:MaintenanceMaximumMilliseconds-or(Get-Date).ToUniversalTime()-ge$script:MaintenanceDeadline){Stop-BoundedProcessTree $process;throw"$Code`_TIMEOUT"}
      if(-not$stdoutDone-and$stdoutTask.IsCompleted){$count=$stdoutTask.GetAwaiter().GetResult();if($count-eq0){$stdoutDone=$true}else{if($stdout.Length+$stderr.Length+$count-gt$MaximumChildOutputBytes){Stop-BoundedProcessTree $process;throw"$Code`_OUTPUT_LIMIT"};$stdout.Write($stdoutBuffer,0,$count);$stdoutTask=$process.StandardOutput.BaseStream.ReadAsync($stdoutBuffer,0,$stdoutBuffer.Length)}}
      if(-not$stderrDone-and$stderrTask.IsCompleted){$count=$stderrTask.GetAwaiter().GetResult();if($count-eq0){$stderrDone=$true}else{if($stdout.Length+$stderr.Length+$count-gt$MaximumChildOutputBytes){Stop-BoundedProcessTree $process;throw"$Code`_OUTPUT_LIMIT"};$stderr.Write($stderrBuffer,0,$count);$stderrTask=$process.StandardError.BaseStream.ReadAsync($stderrBuffer,0,$stderrBuffer.Length)}}
      if(-not($process.HasExited-and$stdoutDone-and$stderrDone)){[Threading.Thread]::Sleep(10)}
    }
    if($process.ExitCode-ne0){throw"$Code`_FAILED"}
    return [Text.Encoding]::UTF8.GetString($stdout.ToArray())
  }finally{
    if($started){Stop-BoundedProcessTree $process};$stdout.Dispose();$stderr.Dispose();$process.Dispose()
  }
}
function New-PgChildEnvironment([string]$PgPass,$Db){return @{PGPASSFILE=$PgPass;PGSSLMODE='verify-full';PGSSLROOTCERT=[IO.Path]::GetFullPath([string]$Db.caCertificatePath);PGCONNECT_TIMEOUT=[string]$PgConnectTimeoutSeconds;PGOPTIONS="-c lock_timeout=$($PgLockTimeoutMilliseconds)ms -c statement_timeout=$($PgStatementTimeoutMilliseconds)ms -c idle_in_transaction_session_timeout=$($PgIdleTransactionTimeoutMilliseconds)ms";PGAPPNAME='meta-ads-security-migration'}}
function InvokeApplied([string]$PgPass,[string]$User,$Db){$sql='SELECT coalesce(string_agg(migration_name || ''='' || checksum, E''\n'' ORDER BY migration_name),'''') FROM "'+[string]$Db.schema+'"."_prisma_migrations" WHERE finished_at IS NOT NULL AND rolled_back_at IS NULL';return(Invoke-BoundedChild $PsqlPath @("--host=$($Db.host)",'--port=5432',"--username=$User","--dbname=$($Db.name)",'--no-password','--tuples-only','--no-align','--set=ON_ERROR_STOP=1',"--command=$sql") (New-PgChildEnvironment $PgPass $Db) 'MIGRATION_APPLIED_QUERY').Trim()}
function InvokeConversion([string]$PgPass,[string]$User,$Db,[string]$SqlPath){[void](Invoke-BoundedChild $PsqlPath @("--host=$($Db.host)",'--port=5432',"--username=$User","--dbname=$($Db.name)",'--no-password','--set=ON_ERROR_STOP=1',"--file=$SqlPath") (New-PgChildEnvironment $PgPass $Db) 'LEGACY_STORAGE_REFERENCE_CONVERSION')}
function Assert-MigrationMaintenanceAndDrain([bool]$RequireFreshDrain){$flag=File $MaintenanceFlagPath 'MAINTENANCE_FLAG_REQUIRED';$drain=File $DrainStatePath 'DRAIN_STATE_REQUIRED';AssertHash $flag $ExpectedMaintenanceFlagSha256 'MAINTENANCE_FLAG_HASH_MISMATCH';AssertHash $drain $ExpectedDrainStateSha256 'DRAIN_STATE_HASH_MISMATCH';$maintenance=Get-Content -Raw -LiteralPath $flag|ConvertFrom-Json;$drainValue=Get-Content -Raw -LiteralPath $drain|ConvertFrom-Json;$drainAt=[datetime]::Parse([string]$drainValue.completedAt).ToUniversalTime();if($maintenance.version-ne1-or$maintenance.enabled-ne$true-or$maintenance.releaseId-cne$config.release.id-or$maintenance.approvalIdDigest-notmatch'^[0-9a-f]{64}$'-or$drainValue.version-ne1-or$drainValue.result-ne'DRAINED'-or$drainValue.activeRequests-ne0-or($RequireFreshDrain-and$drainAt-lt(Get-Date).ToUniversalTime().AddSeconds(-30))-or-not(Get-Process -Id ([int]$drainValue.processId) -ErrorAction SilentlyContinue)){throw'MIGRATION_MAINTENANCE_OR_DRAIN_REJECTED'};return @{Flag=$flag;Drain=$drain}}
function New-MigrationApprovalPlan([string]$IntendedAction){
  if($IntendedAction-notin@('Apply','Finalize')){throw'PLANNED_ACTION_REQUIRED'}
  if($ConfirmProjectRef-notmatch'^[a-z]{20}$'-or$ConfirmDatabaseHost-notmatch'^(?:db\.[a-z]{20}\.supabase\.co|[a-z0-9-]+\.pooler\.supabase\.com)$'-or$ConfirmDatabaseName-notmatch'^[a-z][a-z0-9_]{0,62}$'-or$ConfirmDatabaseSchema-notmatch'^[a-z][a-z0-9_]{0,62}$'){throw'MIGRATION_PLAN_DATABASE_IDENTITY_INVALID'}
  $parameters=[ordered]@{provider='supabase_postgres';projectRef=$ConfirmProjectRef;host=$ConfirmDatabaseHost;port=5432;databaseName=$ConfirmDatabaseName;databaseSchema=$ConfirmDatabaseSchema;previousReleaseKind=$PreviousReleaseKind;runtimeConfigPath=(Get-ApprovalPath $RuntimeConfigPath 'MIGRATION_PLAN_RUNTIME_PATH_REQUIRED');runtimeConfigSha256=(Get-ApprovalHash $ExpectedRuntimeConfigSha256 'MIGRATION_PLAN_RUNTIME_HASH_REQUIRED');migrationPgPassPath=(Get-ApprovalPath $MigrationPgPassFile 'MIGRATION_PLAN_PGPASS_PATH_REQUIRED');migrationPgPassSha256=(Get-ApprovalHash $ExpectedMigrationPgPassSha256 'MIGRATION_PLAN_PGPASS_HASH_REQUIRED');filesystemEvidencePath=(Get-ApprovalPath $FileSystemEvidencePath 'MIGRATION_PLAN_FILESYSTEM_EVIDENCE_PATH_REQUIRED');filesystemEvidenceSha256=(Get-ApprovalHash $ExpectedFileSystemEvidenceSha256 'MIGRATION_PLAN_FILESYSTEM_EVIDENCE_HASH_REQUIRED');preDatabaseBoundaryEvidencePath=(Get-ApprovalPath $PreDatabaseBoundaryEvidencePath 'MIGRATION_PLAN_PRE_BOUNDARY_PATH_REQUIRED');preDatabaseBoundaryEvidenceSha256=(Get-ApprovalHash $ExpectedPreDatabaseBoundaryEvidenceSha256 'MIGRATION_PLAN_PRE_BOUNDARY_HASH_REQUIRED');latestBackupEvidencePath=(Get-ApprovalPath $LatestBackupEvidencePath 'MIGRATION_PLAN_BACKUP_PATH_REQUIRED');latestBackupEvidenceSha256=(Get-ApprovalHash $ExpectedLatestBackupEvidenceSha256 'MIGRATION_PLAN_BACKUP_HASH_REQUIRED');backupReceiptPublicKeyPath=(Get-ApprovalPath $BackupReceiptPublicKeyPath 'MIGRATION_PLAN_PUBLIC_KEY_PATH_REQUIRED');backupReceiptPublicKeySha256=(Get-ApprovalHash $ExpectedBackupReceiptPublicKeySha256 'MIGRATION_PLAN_PUBLIC_KEY_HASH_REQUIRED');targetReleaseRoot=(Get-ApprovalPath $TargetReleaseRoot 'MIGRATION_PLAN_TARGET_RELEASE_ROOT_REQUIRED');targetManifestSha256=(Get-ApprovalHash $ExpectedTargetManifestSha256 'MIGRATION_PLAN_TARGET_MANIFEST_HASH_REQUIRED');compatibilityEvidencePath=(Get-ApprovalPath $CompatibilityEvidencePath 'MIGRATION_PLAN_COMPATIBILITY_PATH_REQUIRED');compatibilityEvidenceSha256=(Get-ApprovalHash $ExpectedCompatibilityEvidenceSha256 'MIGRATION_PLAN_COMPATIBILITY_HASH_REQUIRED');compatibilityGeneratorPath=(Get-ApprovalPath $CompatibilityGeneratorPath 'MIGRATION_PLAN_COMPATIBILITY_GENERATOR_PATH_REQUIRED');compatibilityGeneratorSha256=(Get-ApprovalHash $ExpectedCompatibilityGeneratorSha256 'MIGRATION_PLAN_COMPATIBILITY_GENERATOR_HASH_REQUIRED');nodePath=(Get-ApprovalPath $NodePath 'MIGRATION_PLAN_NODE_PATH_REQUIRED');nodeSha256=(Get-ApprovalHash $ExpectedNodeSha256 'MIGRATION_PLAN_NODE_HASH_REQUIRED');attestationVerifierPath=(Get-ApprovalPath $AttestationVerifierPath 'MIGRATION_PLAN_ATTESTATION_PATH_REQUIRED');attestationVerifierSha256=(Get-ApprovalHash $ExpectedAttestationVerifierSha256 'MIGRATION_PLAN_ATTESTATION_HASH_REQUIRED');prismaCliPath=(Get-ApprovalPath $PrismaCliPath 'MIGRATION_PLAN_PRISMA_PATH_REQUIRED');prismaCliSha256=(Get-ApprovalHash $ExpectedPrismaCliSha256 'MIGRATION_PLAN_PRISMA_HASH_REQUIRED');prismaSchemaPath=(Get-ApprovalPath $PrismaSchemaPath 'MIGRATION_PLAN_SCHEMA_PATH_REQUIRED');migrationsRoot=(Get-ApprovalPath $MigrationsRoot 'MIGRATION_PLAN_MIGRATIONS_ROOT_REQUIRED');psqlPath=(Get-ApprovalPath $PsqlPath 'MIGRATION_PLAN_PSQL_PATH_REQUIRED');psqlSha256=(Get-ApprovalHash $ExpectedPsqlSha256 'MIGRATION_PLAN_PSQL_HASH_REQUIRED');journalPath=(Get-ApprovalPath $JournalPath 'MIGRATION_PLAN_JOURNAL_PATH_REQUIRED');evidenceOutputPath=(Get-ApprovalPath $EvidenceOutputPath 'MIGRATION_PLAN_EVIDENCE_OUTPUT_PATH_REQUIRED')}
  $parameters.maximumMaintenanceDurationSeconds=$MaximumMaintenanceDurationSeconds;$parameters.pgConnectTimeoutSeconds=$PgConnectTimeoutSeconds;$parameters.pgLockTimeoutMilliseconds=$PgLockTimeoutMilliseconds;$parameters.pgStatementTimeoutMilliseconds=$PgStatementTimeoutMilliseconds;$parameters.pgIdleTransactionTimeoutMilliseconds=$PgIdleTransactionTimeoutMilliseconds;$parameters.maximumChildOutputBytes=$MaximumChildOutputBytes
  if($PreviousReleaseKind-eq'LOCAL_RELEASE'){$parameters.previousReleaseRoot=Get-ApprovalPath $PreviousReleaseRoot 'MIGRATION_PLAN_PREVIOUS_RELEASE_ROOT_REQUIRED';$parameters.previousManifestSha256=Get-ApprovalHash $ExpectedPreviousManifestSha256 'MIGRATION_PLAN_PREVIOUS_MANIFEST_HASH_REQUIRED'}else{$parameters.legacyBaselineEvidencePath=Get-ApprovalPath $LegacyBaselineEvidencePath 'MIGRATION_PLAN_LEGACY_BASELINE_PATH_REQUIRED';$parameters.legacyBaselineEvidenceSha256=Get-ApprovalHash $ExpectedLegacyBaselineEvidenceSha256 'MIGRATION_PLAN_LEGACY_BASELINE_HASH_REQUIRED';$parameters.legacyQuiesceEvidencePath=Get-ApprovalPath $LegacyQuiesceEvidencePath 'MIGRATION_PLAN_LEGACY_QUIESCE_PATH_REQUIRED';$parameters.legacyQuiesceEvidenceSha256=Get-ApprovalHash $ExpectedLegacyQuiesceEvidenceSha256 'MIGRATION_PLAN_LEGACY_QUIESCE_HASH_REQUIRED'}
  $parameters.maintenanceFlagPath=Get-ApprovalPath $MaintenanceFlagPath 'MIGRATION_PLAN_MAINTENANCE_PATH_REQUIRED';$parameters.maintenanceFlagSha256=Get-ApprovalHash $ExpectedMaintenanceFlagSha256 'MIGRATION_PLAN_MAINTENANCE_HASH_REQUIRED';$parameters.drainStatePath=Get-ApprovalPath $DrainStatePath 'MIGRATION_PLAN_DRAIN_PATH_REQUIRED';$parameters.drainStateSha256=Get-ApprovalHash $ExpectedDrainStateSha256 'MIGRATION_PLAN_DRAIN_HASH_REQUIRED'
  if($IntendedAction-eq'Finalize'){$parameters.migrationJournalSha256=Get-ApprovalHash $ExpectedMigrationJournalSha256 'MIGRATION_PLAN_JOURNAL_HASH_REQUIRED';$parameters.postDatabaseBoundaryEvidencePath=Get-ApprovalPath $PostDatabaseBoundaryEvidencePath 'MIGRATION_PLAN_POST_BOUNDARY_PATH_REQUIRED';$parameters.postDatabaseBoundaryEvidenceSha256=Get-ApprovalHash $ExpectedPostDatabaseBoundaryEvidenceSha256 'MIGRATION_PLAN_POST_BOUNDARY_HASH_REQUIRED'}
  $target="Exact existing Supabase PostgreSQL target $ConfirmProjectRef/$ConfirmDatabaseHost`:5432/$ConfirmDatabaseName schema $ConfirmDatabaseSchema"
  $impact=if($IntendedAction-eq'Apply'){'Under maintenance and drain, writes an intent journal, applies the hash-pinned legacy reference conversion when present, then deploys only the target migration chain; final PASS is not emitted'}else{'After Apply, verifies a fresh exact post-boundary and applied chain, then writes finalized non-secret migration evidence'}
  $rollback=if($PreviousReleaseKind-eq'LEGACY_BASELINE'){'Separately approve restoration of the signed pre-change DB backup, then separately approve exact legacy restart; rollback-code compatibility is not claimed'}else{'Separately approve restoration of the signed pre-change DB backup and the compatible previous local release'}
  return New-ApprovalPlan $PSCommandPath $IntendedAction $parameters $target $impact $rollback
}
if($Action-eq'Plan'){New-MigrationApprovalPlan $PlannedAction|ConvertTo-Json -Depth 12;exit 0}
$migrationMutation=if($Action-in@('Apply','Finalize')){$Action}else{$null};if($migrationMutation){Assert-ApprovedPlan (New-MigrationApprovalPlan $migrationMutation) ([bool]$Approved) $ApprovedPlanSha256}
$runtime=File $RuntimeConfigPath 'RUNTIME_CONFIG_NOT_FOUND';$config=Get-Content -Raw -LiteralPath $runtime|ConvertFrom-Json;$db=$config.database
AssertHash $runtime $ExpectedRuntimeConfigSha256 'RUNTIME_CONFIG_HASH_MISMATCH'
if($db.provider-ne'supabase_postgres'-or$db.port-ne5432-or$ConfirmProjectRef-cne$db.projectRef-or$ConfirmDatabaseHost-cne$db.host-or$ConfirmDatabaseName-cne$db.name-or$ConfirmDatabaseSchema-cne$db.schema){throw'MIGRATION_TARGET_CONFIRMATION_MISMATCH'}
$node=File $NodePath 'NODE_NOT_FOUND';$verifier=File $AttestationVerifierPath 'ATTESTATION_VERIFIER_NOT_FOUND';$publicKey=File $BackupReceiptPublicKeyPath 'BACKUP_RECEIPT_PUBLIC_KEY_NOT_FOUND';$prisma=File $PrismaCliPath 'PRISMA_CLI_NOT_FOUND';$schema=File $PrismaSchemaPath 'PRISMA_SCHEMA_NOT_FOUND';$pgpass=File $MigrationPgPassFile 'MIGRATION_PGPASS_NOT_FOUND';$psql=File $PsqlPath 'PSQL_NOT_FOUND';$migrations=Directory $MigrationsRoot 'MIGRATIONS_ROOT_NOT_FOUND';$targetRoot=Directory $TargetReleaseRoot 'TARGET_RELEASE_NOT_FOUND';if($PreviousReleaseKind-eq'LOCAL_RELEASE'){$previousRoot=Directory $PreviousReleaseRoot 'PREVIOUS_RELEASE_NOT_FOUND'}else{$legacyBaselinePath=File $LegacyBaselineEvidencePath 'LEGACY_BASELINE_NOT_FOUND';AssertHash $legacyBaselinePath $ExpectedLegacyBaselineEvidenceSha256 'LEGACY_BASELINE_HASH_MISMATCH';$legacyQuiescePath=File $LegacyQuiesceEvidencePath 'LEGACY_QUIESCE_EVIDENCE_NOT_FOUND';AssertHash $legacyQuiescePath $ExpectedLegacyQuiesceEvidenceSha256 'LEGACY_QUIESCE_EVIDENCE_HASH_MISMATCH'};$fsPath=File $FileSystemEvidencePath 'FILESYSTEM_EVIDENCE_NOT_FOUND';$backupPath=File $LatestBackupEvidencePath 'LATEST_BACKUP_EVIDENCE_NOT_FOUND';$compatibilityPath=File $CompatibilityEvidencePath 'COMPATIBILITY_EVIDENCE_NOT_FOUND';$compatibilityGenerator=File $CompatibilityGeneratorPath 'COMPATIBILITY_GENERATOR_NOT_FOUND';$journal=OutputPath $JournalPath 'MIGRATION_JOURNAL_PATH_REQUIRED';$output=OutputPath $EvidenceOutputPath 'MIGRATION_EVIDENCE_PATH_REQUIRED'
$PsqlPath=$psql
AssertHash $pgpass $ExpectedMigrationPgPassSha256 'MIGRATION_PGPASS_HASH_MISMATCH';AssertHash $fsPath $ExpectedFileSystemEvidenceSha256 'FILESYSTEM_EVIDENCE_HASH_MISMATCH';AssertHash $publicKey $ExpectedBackupReceiptPublicKeySha256 'BACKUP_RECEIPT_PUBLIC_KEY_HASH_MISMATCH'
